using System.Numerics;
using System.Security.Cryptography;
using System.Text;
using AgentBridge.Roster;

// Fixed P-256 test keys with deterministic signatures (RFC 6979, low-S), so the committed vectors
// are regenerated byte for byte. Test code only: real signing keys sign with the platform
// (§6.2), whose signatures are randomized and verify the same way.
public sealed class TestKey
{
    static readonly BigInteger P = Hex("ffffffff00000001000000000000000000000000ffffffffffffffffffffffff");
    static readonly BigInteger N = Hex("ffffffff00000000ffffffffffffffffbce6faada7179e84f3b9cac2fc632551");
    static readonly BigInteger Gx = Hex("6b17d1f2e12c4247f8bce6e563a440f277037d812deb33a0f4a13945d898c296");
    static readonly BigInteger Gy = Hex("4fe342e2fe1a7f9b8ee7eb4a7c0f9e162bce33576b315ececbb6406837bf51f5");

    public string Name { get; }
    public BigInteger D { get; }
    public byte[] Public { get; }
    public string Device => Ids.Device(Public);

    TestKey(string name, BigInteger d)
    {
        Name = name;
        D = d;
        var (x, y) = Multiply(d, Gx, Gy);
        Public = [0x04, .. Bytes(x), .. Bytes(y)];
    }

    // The key named `name`: d = SHA-256("agent-bridge roster test key " + name) mod n.
    public static TestKey Named(string name)
    {
        var d = Unsigned(SHA256.HashData(Encoding.UTF8.GetBytes("agent-bridge roster test key " + name))) % N;
        return new TestKey(name, d);
    }

    // ECDSA over SHA-256(message), k from RFC 6979, as minimal low-S DER.
    public byte[] Sign(byte[] message)
    {
        var h = SHA256.HashData(message);
        var z = Unsigned(h) % N;
        var k = Nonce(z);
        var (x, _) = Multiply(k, Gx, Gy);
        var r = x % N;
        var s = Inverse(k, N) * (z + r * D) % N;
        return P256.Der(r, s <= N >> 1 ? s : N - s);
    }

    public System.Text.Json.Nodes.JsonObject Json() => new()
    {
        ["d"] = Bytes(D).ToHex(),
        ["public"] = Codec.Base64Url(Public),
        ["device"] = Device,
    };

    BigInteger Nonce(BigInteger z)
    {
        var x = Bytes(D);
        var h1 = Bytes(z);
        var v = Enumerable.Repeat((byte)1, 32).ToArray();
        var k = new byte[32];
        k = HMACSHA256.HashData(k, (byte[])[.. v, 0, .. x, .. h1]);
        v = HMACSHA256.HashData(k, v);
        k = HMACSHA256.HashData(k, (byte[])[.. v, 1, .. x, .. h1]);
        v = HMACSHA256.HashData(k, v);
        while (true)
        {
            v = HMACSHA256.HashData(k, v);
            var candidate = Unsigned(v);
            if (candidate > 0 && candidate < N) { return candidate; }
            k = HMACSHA256.HashData(k, (byte[])[.. v, 0]);
            v = HMACSHA256.HashData(k, v);
        }
    }

    // Double-and-add in Jacobian coordinates, so a signature takes one inversion.
    static (BigInteger X, BigInteger Y) Multiply(BigInteger scalar, BigInteger x, BigInteger y)
    {
        (BigInteger X, BigInteger Y, BigInteger Z) acc = (0, 1, 0);
        (BigInteger X, BigInteger Y, BigInteger Z) add = (x, y, 1);
        for (var i = (int)scalar.GetBitLength() - 1; i >= 0; i--)
        {
            acc = Double(acc);
            if (!(scalar >> i).IsEven) { acc = Add(acc, add); }
        }
        var zi = Inverse(acc.Z, P);
        var zi2 = zi * zi % P;
        return (acc.X * zi2 % P, acc.Y * zi2 % P * zi % P);
    }

    static (BigInteger, BigInteger, BigInteger) Double((BigInteger X, BigInteger Y, BigInteger Z) p)
    {
        if (p.Z.IsZero || p.Y.IsZero) { return (0, 1, 0); }
        var ysq = p.Y * p.Y % P;
        var s = 4 * p.X * ysq % P;
        var z2 = p.Z * p.Z % P;
        var m = 3 * (p.X - z2) * (p.X + z2) % P;
        var x3 = Mod(m * m - 2 * s);
        var y3 = Mod(m * (s - x3) - 8 * ysq * ysq);
        var z3 = 2 * p.Y * p.Z % P;
        return (x3, y3, z3);
    }

    static (BigInteger, BigInteger, BigInteger) Add((BigInteger X, BigInteger Y, BigInteger Z) p, (BigInteger X, BigInteger Y, BigInteger Z) q)
    {
        if (p.Z.IsZero) { return q; }
        var z1 = p.Z * p.Z % P;
        var u2 = q.X * z1 % P;
        var s2 = q.Y * z1 % P * p.Z % P;
        var h = Mod(u2 - p.X);
        var r = Mod(s2 - p.Y);
        if (h.IsZero) { return r.IsZero ? Double(p) : (0, 1, 0); }
        var h2 = h * h % P;
        var h3 = h2 * h % P;
        var x3 = Mod(r * r - h3 - 2 * p.X * h2);
        var y3 = Mod(r * (p.X * h2 - x3) - p.Y * h3);
        var z3 = p.Z * h % P;
        return (x3, y3, z3);
    }

    static BigInteger Mod(BigInteger v) => (v % P + P) % P;

    static BigInteger Inverse(BigInteger v, BigInteger m) => BigInteger.ModPow(v, m - 2, m);

    static BigInteger Hex(string hex) => BigInteger.Parse("0" + hex, System.Globalization.NumberStyles.HexNumber);

    static BigInteger Unsigned(ReadOnlySpan<byte> b) => new(b, isUnsigned: true, isBigEndian: true);

    public static byte[] Bytes(BigInteger v)
    {
        var raw = v.ToByteArray(isUnsigned: true, isBigEndian: true);
        var bytes = new byte[32];
        raw.CopyTo(bytes, 32 - raw.Length);
        return bytes;
    }
}

public static class HexText
{
    public static string ToHex(this byte[] bytes) => Convert.ToHexStringLower(bytes);

    public static byte[] FromHex(this string hex) => Convert.FromHexString(hex);
}
